For every purchase_order document, contractId is required and must be a complete citation object, never null or omitted. When the PO prints a reference such as "contract C-001", return {"value":"C-001","sourceId":"<that PO's input ID>","page":<printed page number>,"excerpt":"<exact substring containing contract C-001>"}. Do not use the PO's own ID or filename as the contract value, and do not infer or fabricate a citation if the reference is absent or unclear.
Every factual field must be a citation object exactly shaped as {"value": ..., "sourceId": "...", "page": 1, "excerpt": "..."}. Keep numeric values numeric, page numbers integers, dates YYYY-MM-DD strings, and currency INR. Each excerpt must be an exact substring from that sourceId and page and must support the value. Never transfer a citation between documents, infer facts, or fabricate missing citations. Preserve each input document's ID and type exactly; use only contract, purchase_order, invoice, amendment.
The following synthetic example shows the citation and type-specific nested structure. Its values and citations are illustrative only; never copy them. In the response, also include every schema-required field that is inapplicable to a type as null. Use the actual supplied source text and cite each claim from its own source page:
{"documents":[{"type":"contract","id":{"value":"C1","sourceId":"C1","page":1,"excerpt":"Contract C1"},"supplierId":{"value":"S1","sourceId":"C1","page":1,"excerpt":"Supplier S1"},"currency":{"value":"INR","sourceId":"C1","page":1,"excerpt":"INR"},"validFrom":{"value":"2025-01-01","sourceId":"C1","page":1,"excerpt":"2025-01-01"},"prices":[{"sku":{"value":"SKU-X","sourceId":"C1","page":1,"excerpt":"SKU-X"},"unitPrice":{"value":100,"sourceId":"C1","page":1,"excerpt":"100"}}]},{"type":"purchase_order","id":{"value":"P1","sourceId":"P1","page":1,"excerpt":"PO P1"},"supplierId":{"value":"S1","sourceId":"P1","page":1,"excerpt":"Supplier S1"},"contractId":{"value":"C1","sourceId":"P1","page":1,"excerpt":"Contract C1"},"currency":{"value":"INR","sourceId":"P1","page":1,"excerpt":"INR"},"orderedAt":{"value":"2025-07-01","sourceId":"P1","page":1,"excerpt":"2025-07-01"},"items":[{"sku":{"value":"SKU-X","sourceId":"P1","page":1,"excerpt":"SKU-X"},"quantity":{"value":10,"sourceId":"P1","page":1,"excerpt":"quantity 10"},"unitPrice":{"value":100,"sourceId":"P1","page":1,"excerpt":"price 100"}}]},{"type":"invoice","id":{"value":"I1","sourceId":"I1","page":1,"excerpt":"Invoice I1"},"supplierId":{"value":"S1","sourceId":"I1","page":1,"excerpt":"Supplier S1"},"purchaseOrderId":{"value":"P1","sourceId":"I1","page":1,"excerpt":"PO P1"},"currency":{"value":"INR","sourceId":"I1","page":1,"excerpt":"INR"},"issuedAt":{"value":"2025-07-02","sourceId":"I1","page":1,"excerpt":"2025-07-02"},"items":[{"sku":{"value":"SKU-X","sourceId":"I1","page":1,"excerpt":"SKU-X"},"quantity":{"value":10,"sourceId":"I1","page":1,"excerpt":"quantity 10"},"unitPrice":{"value":120,"sourceId":"I1","page":1,"excerpt":"price 120"}}]}]}
For amendments, return type amendment with cited id, supplierId, contractId, currency, effectiveFrom, optional effectiveTo, and prices entries containing cited sku and unitPrice. Do not add fields. Do not output commentary or markdown.`;
export type ModelExtractor = (docs: SourceDocument[]) => Promise<unknown>;
export type DiagnosticCategory = "offline_mode" | "missing_configuration" | "invalid_configuration" | "input_limit" | "groq_http" | "timeout" | "network_error" | "invalid_json" | "schema_validation" | "missing_evidence" | "unsupported_evidence";
export type StructuralFailure = { field: string; reason: "missing" | "null" | "wrong_type" | "invalid_value" | "unknown_structure" };
export type SafeDiagnostic = { category: DiagnosticCategory; status?: number; fields?: string[]; structuralFailures?: StructuralFailure[]; providerCode?: string; providerType?: string; param?: string; providerKeyword?: string };
export type EvidenceReference = { field: string; sourceId: string; page: number; excerpt: string };
export type SelfAudit = { proposedFinding: string; checks: { name: string; result: "passed" | "failed" | "not_verified"; explanation: string }[]; supportingEvidence: EvidenceReference[]; contradictoryEvidence: EvidenceReference[]; disposition: "supported" | "rejected" | "needs_review"; explanation: string };
export type InvestigationResult = { state: "completed" | "needs_review"; case: ReturnType<typeof auditDocuments> | null; evidence: EvidenceReference[]; warnings: string[]; states: string[]; selfAudit?: SelfAudit[]; diagnostic?: SafeDiagnostic };

class DiagnosticError extends Error {
  constructor(readonly diagnostic: SafeDiagnostic) { super(diagnostic.category); }
}
const safeFields = (paths: PropertyKey[][]) => {
  const allowed = new Set(["documents", "type", "id", "supplierId", "currency", "validFrom", "validTo", "effectiveFrom", "effectiveTo", "contractId", "purchaseOrderId", "issuedAt", "orderedAt", "prices", "items", "sku", "quantity", "unitPrice", "value", "sourceId", "page", "excerpt", "choices", "message", "content"]);
  return [...new Set(paths.map(path => path.map(part => typeof part === "number" ? `[${part}]` : allowed.has(String(part)) ? String(part) : "<key>").join(".").replace(/\.\[/g, "[")))];
};
const parseSafeFieldPath = (path: string): PropertyKey[] => (path.match(/[^.[\]]+|\[(\d+)\]/g) ?? []).map(part => {
      const reconciled = normalizeModelFacts(candidate, input.documents);
      const facts = extractedFactsSchema.parse(reconciled);
      states.push("match");
      await tracedMatching(async () => { verify(facts, input.documents); });
      states.push("investigate");
      states.push("challenge");
      const result = await tracedInvestigation(() => buildCase(facts, input.documents, states));
      return { ...result, states: [...result.states.slice(0, -1), result.state] };
  } catch (error) {
      const diagnostic = error instanceof DiagnosticError ? error.diagnostic : error instanceof z.ZodError ? safeSchemaDiagnostic(error, candidate) : { category: "schema_validation" as const };
      return { state: "needs_review", case: null, evidence: [], warnings: ["Extraction failed; manual review is required"], states: [...states, "needs_review"], diagnostic };
  }
}

async function buildCase(facts: ExtractedFacts, docs: SourceDocument[], states: InvestigationResult["states"]): Promise<InvestigationResult> {
  const contracts = facts.documents.filter((d): d is ExtractedFacts["documents"][number] & { type: "contract" } => d.type === "contract");
  const amendments = facts.documents.filter(d => d.type === "amendment");
  const pos = facts.documents.filter(d => d.type === "purchase_order");
  const invoices = facts.documents.filter(d => d.type === "invoice");
  if (contracts.length !== 1 || pos.length !== 1 || !invoices.length || facts.documents.length !== 1 + pos.length + invoices.length + amendments.length) return review("Expected one contract, one PO, at least one invoice, and any amendments", states);
  const base = contracts[0];
  const po = pos[0];
  const inv = invoices;
  if (base.supplierId.value !== po.supplierId.value || base.id.value !== po.contractId.value || inv.some(i => i.supplierId.value !== base.supplierId.value || i.purchaseOrderId.value !== po.id.value)) return review("Supplier, contract, or PO references conflict", states);
  const amendmentAt = (date: string) => amendments.filter(a => a.contractId.value === base.id.value && a.supplierId.value === base.supplierId.value && a.effectiveFrom.value <= date && (!a.effectiveTo || date <= a.effectiveTo.value)).sort((a, b) => a.effectiveFrom.value.localeCompare(b.effectiveFrom.value)).at(-1);
  const applicable = amendments.filter(a => a.contractId.value === base.id.value && a.supplierId.value === base.supplierId.value && a.effectiveFrom.value <= inv[0].issuedAt.value && (!a.effectiveTo || inv[0].issuedAt.value <= a.effectiveTo.value));
  if (amendments.some(a => a.contractId.value !== base.id.value || a.supplierId.value !== base.supplierId.value)) return review("Amendment references a different supplier or contract", states);
  applicable.sort((a, b) => a.effectiveFrom.value.localeCompare(b.effectiveFrom.value));
  if (applicable.length > 1 && applicable.at(-1)!.effectiveFrom.value === applicable.at(-2)!.effectiveFrom.value) return review("Conflicting amendments have the same effective date", states);
  if (inv.some(i => (amendmentAt(i.issuedAt.value)?.id.value ?? "base") !== (amendmentAt(inv[0].issuedAt.value)?.id.value ?? "base"))) return review("Invoices span different amendment periods; compare each period separately", states);
  const amendment = applicable.at(-1);
  const prices = new Map(base.prices.map(x => [x.sku.value, x.unitPrice.value]));
  for (const a of applicable) for (const p of a.prices) prices.set(p.sku.value, p.unitPrice.value);
  const contract = { type: "contract", id: base.id.value, supplierId: base.supplierId.value, currency: base.currency.value, validFrom: amendment?.effectiveFrom.value ?? base.validFrom.value, ...(amendment?.effectiveTo ? { validTo: amendment.effectiveTo.value } : base.validTo ? { validTo: base.validTo.value } : {}), prices: [...prices].map(([sku, unitPrice]) => ({ sku, unitPrice })), evidence: amendment ? amendment.prices.map(p => p.unitPrice.excerpt).join("; ") : base.prices.map(p => p.unitPrice.excerpt).join("; ") };
  const toSimple = (d: typeof po | typeof inv[number]) => ({ type: d.type, id: d.id.value, supplierId: d.supplierId.value, ...(d.type === "purchase_order" ? { contractId: d.contractId.value, orderedAt: d.orderedAt.value } : { purchaseOrderId: d.purchaseOrderId.value, issuedAt: d.issuedAt.value }), currency: d.currency.value, items: d.items.map(x => ({ sku: x.sku.value, quantity: x.quantity.value, unitPrice: x.unitPrice.value })) });
  const audit = auditDocuments({ contract, purchaseOrder: toSimple(po), invoices: inv.map(toSimple) });
  const citations = allFacts(facts).filter(c => c.sourceId && docs.some(d => d.id === c.sourceId));
  const evidence = citations.map(c => ({ ...c }));
  const challenged = await tracedChallenge(() => audit.findings.map(finding => {
    const invoice = inv.find(i => i.id.value === finding.invoiceId);
    const poLine = po.items.find(item => item.sku.value === finding.sku);
    const applicableAmendments = amendments.filter(a => invoice && a.contractId.value === base.id.value && a.supplierId.value === base.supplierId.value && a.effectiveFrom.value <= invoice.issuedAt.value && (!a.effectiveTo || invoice.issuedAt.value <= a.effectiveTo.value));
    const conflictingAmendmentIds = new Set(applicableAmendments.filter(a => a.prices.some(p => p.sku.value === finding.sku && poLine && p.unitPrice.value !== poLine.unitPrice.value)).map(a => a.id.value));
    const relevantPriceEvidence = evidence.filter(e => e.field.includes("unitPrice") && (e.sourceId === finding.invoiceId || e.sourceId === po.id.value || e.sourceId === base.id.value || applicableAmendments.some(a => a.id.value === e.sourceId)));
    const supported = relevantPriceEvidence.filter(e => e.sourceId === finding.invoiceId || e.sourceId === po.id.value || e.sourceId === base.id.value || applicableAmendments.some(a => a.id.value === e.sourceId && !conflictingAmendmentIds.has(a.id.value)));
    const contradictory = relevantPriceEvidence.filter(e => conflictingAmendmentIds.has(e.sourceId) || (e.sourceId === po.id.value && finding.status === "needs_review"));
    const isUnresolved = finding.status === "needs_review" || audit.status === "needs_review";
    return {
      proposedFinding: `${finding.invoiceId} · ${finding.sku}: ${finding.reason}`,
      checks: [
        { name: "Citation integrity", result: "passed" as const, explanation: "Every extracted fact used here matched an exact excerpt on its cited source page." },
        { name: "Supplier, contract, and PO identity", result: "passed" as const, explanation: "Document references reconciled before line comparison." },
        { name: "Applicable price and PO agreement", result: isUnresolved ? "failed" as const : "passed" as const, explanation: isUnresolved ? "A price, quantity, validity, or agreement conflict prevents a supported claim." : "The selected agreed price and PO line reconcile." },
        { name: "Decisive facts", result: isUnresolved ? "not_verified" as const : "passed" as const, explanation: isUnresolved ? "At least one decisive check remains unresolved." : "Dates, currency, SKU, quantity, and cited prices were available for deterministic comparison." }
      ],
      supportingEvidence: supported,
      contradictoryEvidence: contradictory,
      proposedDisposition: isUnresolved ? "needs_review" as const : finding.status === "potential_overcharge" ? "supported" as const : "rejected" as const,
      explanation: isUnresolved ? "The proposed discrepancy is not promoted: conflicting or incomplete agreement evidence requires human review." : finding.status === "potential_overcharge" ? "…3456 tokens truncated…><span>The case could not be approved as a completed comparison. Resolve the warning or document identity issue and investigate again.</span></div>}
      {result.case && <><div className="metric-grid"><div className="metric-card metric-primary"><span>Potential overcharge</span><strong>{result.state === "needs_review" ? "Unresolved" : fmt(result.case.totalPotentialOvercharge)}</strong><small>{result.state === "needs_review" ? "No verified amount" : "Calculated from checked invoice lines"}</small></div><div className="metric-card"><span>Invoices reviewed</span><strong>{result.case.checkedInvoices}</strong><small>Unique invoice records in this case</small></div><div className="metric-card"><span>Findings</span><strong>{result.case.findings.length || (result.state === "needs_review" ? "—" : "None")}</strong><small>{result.state === "needs_review" ? "Review outcome unresolved" : "Potential discrepancies"}</small></div></div>
      <div className="card findings-card"><div className="section-head"><div><div className="step">LINE ITEM REVIEW</div><h2>Price comparisons</h2></div><span className="quiet-pill">All amounts INR</span></div>{result.case.findings.length === 0 && result.state === "completed" ? <div className="zero-findings"><span className="zero-check">✓</span><div><strong>No findings in checked lines</strong><p>The completed case found no potential overcharge for the supplied documents.</p></div></div> : result.case.findings.length === 0 ? <div className="review-empty"><strong>No verified comparison is available.</strong><span>Resolve the review notes before treating this case as a zero result.</span></div> : result.case.findings.map((f, i) => <article className="finding-row" key={`${f.invoiceId}-${f.sku}-${i}`}><div className="finding-head"><strong>{f.invoiceId} <span>·</span> {f.sku}</strong><span className={f.status === "needs_review" ? "finding-tag review-tag" : "finding-tag"}>{f.status === "needs_review" ? "REVIEW" : "POTENTIAL OVERCHARGE"}</span></div><p>{f.reason}</p><div className="comparison"><div><small>Contract unit price</small><strong>{f.expectedUnitPrice === undefined ? "Not established" : `${fmt(f.expectedUnitPrice)} / unit`}</strong></div><b aria-hidden="true">→</b><div><small>PO unit price</small><strong>{f.status === "potential_overcharge" && f.expectedUnitPrice !== undefined ? `${fmt(f.expectedUnitPrice)} / unit` : "Review source evidence"}</strong></div><b aria-hidden="true">→</b><div><small>Invoice unit price</small><strong>{fmt(f.billedUnitPrice)} / unit</strong></div><div><small>Quantity</small><strong>{f.quantity.toLocaleString("en-IN")}</strong></div><div className="line-total"><small>Potential line amount</small><strong>{f.potentialOvercharge === undefined ? "Review required" : fmt(f.potentialOvercharge)}</strong></div></div></article>)}</div></>}
      {(result.warnings.length > 0 || result.diagnostic) && <div className="warnings-box"><strong>Warnings and review notes</strong>{result.warnings.map((w, i) => <p key={i}>{w}</p>)}{result.diagnostic && <p>Diagnostic: {result.diagnostic.category}{result.diagnostic.status ? ` (HTTP ${result.diagnostic.status})` : ""}{result.diagnostic.fields?.length ? ` · Fields: ${result.diagnostic.fields.join(", ")}` : ""}</p>}</div>}
      <section className="card evidence-card"><div className="evidence-toolbar"><div><div className="step">SOURCE DOCUMENTS</div><h2>Evidence explorer</h2><p>Exact excerpts from uploaded page text. Search finds text within source references and evidence.</p></div><label className="search-box"><span aria-hidden="true">⌕</span><input value={filter} onChange={e => setFilter(e.target.value)} placeholder="Search evidence" aria-label="Search evidence"/></label></div>{filteredEvidence.length === 0 ? <p className="empty-evidence">No evidence matches this search. Try a document ID, field or phrase.</p> : <div className="evidence-list">{Object.entries(groupedEvidence).map(([sourceId, excerpts]) => <details className="source-group" key={sourceId} open><summary><span className="source-doc-mark">PDF</span><span className="source-doc-title"><strong>{sourceId}</strong><small>{excerpts.length} verified {excerpts.length === 1 ? "excerpt" : "excerpts"}</small></span><span className="source-pages">{[...new Set(excerpts.map(e => e.page))].map(page => `Page ${page}`).join(" · ")}</span><span className="source-chevron" aria-hidden="true">⌄</span></summary><div className="source-excerpts">{excerpts.map((e, i) => <article className="evidence-item" key={`${e.page}-${e.field}-${i}`}><div className="evidence-meta"><span>PAGE {e.page}</span><span>{e.field.replaceAll(".", " / ").replaceAll("[", " ").replaceAll("]", "")}</span></div><blockquote>“{e.excerpt}”</blockquote></article>)}</div></details>)}</div>}</section>
      <p className="disclaimer">Potential discrepancy only. MarginGhost does not approve a claim, contact suppliers or change payments.</p>
    </section>}
