async function buildCase(facts: ExtractedFacts, docs: SourceDocument[], states: InvestigationResult["states"]): Promise<InvestigationResult> {
  const contracts = facts.documents.filter((d): d is ExtractedFacts["documents"][number] & { type: "contract" } => d.type === "contract");
  const amendments = facts.documents.filter(d => d.type === "amendment");
  const pos = facts.documents.filter(d => d.type === "purchase_order");
  const invoices = facts.documents.filter(d => d.type === "invoice");
  if (contracts.length !== 1 || pos.length !== 1 || !invoices.length || facts.documents.length !== 1 + pos.length + invoices.length + amendments.length) return review("Expected one contract, one PO, at least one invoice, and any amendments", states);
  const base = contracts[0];
  const po = pos[0];
  const inv = invoices;
  if (base.supplierId.value !== po.supplierId.value || base.id.value !== po.contractId.value || inv.some(i => i.supplierId.value !== base.supplierId.value || i.purchaseOrderId.value !== po.id.value)) return review("Supplier, contract, or PO references conflict", states);
  const amendmentAt = (date: string) => amendments.filter(a => a.contractId.value === base.id.value && a.supplierId.value === base.supplierId.value && a.effectiveFrom.value <= date && (!a.effectiveTo || date <= a.effectiveTo.value)).sort((a, b) => a.effectiveFrom.value.localeCompare(b.effectiveFrom.value)).at(-1);
  const applicable = amendments.filter(a => a.contractId.value === base.id.value && a.supplierId.value === base.supplierId.value && a.effectiveFrom.value <= inv[0].issuedAt.value && (!a.effectiveTo || inv[0].issuedAt.value <= a.effectiveTo.value));
  if (amendments.some(a => a.contractId.value !== base.id.value || a.supplierId.value !== base.supplierId.value)) return review("Amendment references a different supplier or contract", states);
  applicable.sort((a, b) => a.effectiveFrom.value.localeCompare(b.effectiveFrom.value));
  if (applicable.length > 1 && applicable.at(-1)!.effectiveFrom.value === applicable.at(-2)!.effectiveFrom.value) return review("Conflicting amendments have the same effective date", states);
  if (inv.some(i => (amendmentAt(i.issuedAt.value)?.id.value ?? "base") !== (amendmentAt(inv[0].issuedAt.value)?.id.value ?? "base"))) return review("Invoices span different amendment periods; compare each period separately", states);
  const amendment = applicable.at(-1);
  const prices = new Map(base.prices.map(x => [x.sku.value, x.unitPrice.value]));
  for (const a of applicable) for (const p of a.prices) prices.set(p.sku.value, p.unitPrice.value);
  const contract = { type: "contract", id: base.id.value, supplierId: base.supplierId.value, currency: base.currency.value, validFrom: amendment?.effectiveFrom.value ?? base.validFrom.value, ...(amendment?.effectiveTo ? { validTo: amendment.effectiveTo.value } : base.validTo ? { validTo: base.validTo.value } : {}), prices: [...prices].map(([sku, unitPrice]) => ({ sku, unitPrice })), evidence: amendment ? amendment.prices.map(p => p.unitPrice.excerpt).join("; ") : base.prices.map(p => p.unitPrice.excerpt).join("; ") };
  const toSimple = (d: typeof po | typeof inv[number]) => ({ type: d.type, id: d.id.value, supplierId: d.supplierId.value, ...(d.type === "purchase_order" ? { contractId: d.contractId.value, orderedAt: d.orderedAt.value } : { purchaseOrderId: d.purchaseOrderId.value, issuedAt: d.issuedAt.value }), currency: d.currency.value, items: d.items.map(x => ({ sku: x.sku.value, quantity: x.quantity.value, unitPrice: x.unitPrice.value })) });
  const audit = auditDocuments({ contract, purchaseOrder: toSimple(po), invoices: inv.map(toSimple) });
  const citations = allFacts(facts).filter(c => c.sourceId && docs.some(d => d.id === c.sourceId));
  const evidence = citations.map(c => ({ ...c }));
  const challenged = await tracedChallenge(() => audit.findings.map(finding => {
    const invoice = inv.find(i => i.id.value === finding.invoiceId);
    const poLine = po.items.find(item => item.sku.value === finding.sku);
    const applicableAmendments = amendments.filter(a => invoice && a.contractId.value === base.id.value && a.supplierId.value === base.supplierId.value && a.effectiveFrom.value <= invoice.issuedAt.value && (!a.effectiveTo || invoice.issuedAt.value <= a.effectiveTo.value));
    const conflictingAmendmentIds = new Set(applicableAmendments.filter(a => a.prices.some(p => p.sku.value === finding.sku && poLine && p.unitPrice.value !== poLine.unitPrice.value)).map(a => a.id.value));
    const relevantPriceEvidence = evidence.filter(e => e.field.includes("unitPrice") && (e.sourceId === finding.invoiceId || e.sourceId === po.id.value || e.sourceId === base.id.value || applicableAmendments.some(a => a.id.value === e.sourceId)));
    const supported = relevantPriceEvidence.filter(e => e.sourceId === finding.invoiceId || e.sourceId === po.id.value || e.sourceId === base.id.value || applicableAmendments.some(a => a.id.value === e.sourceId && !conflictingAmendmentIds.has(a.id.value)));
    const contradictory = relevantPriceEvidence.filter(e => conflictingAmendmentIds.has(e.sourceId) || (e.sourceId === po.id.value && finding.status === "needs_review"));
    const isUnresolved = finding.status === "needs_review" || audit.status === "needs_review";
    return {
      proposedFinding: `${finding.invoiceId} · ${finding.sku}: ${finding.reason}`,
      checks: [
        { name: "Citation integrity", result: "passed" as const, explanation: "Every extracted fact used here matched an exact excerpt on its cited source page." },
        { name: "Supplier, contract, and PO identity", result: "passed" as const, explanation: "Document references reconciled before line comparison." },
        { name: "Applicable price and PO agreement", result: isUnresolved ? "failed" as const : "passed" as const, explanation: isUnresolved ? "A price, quantity, validity, or agreement conflict prevents a supported claim." : "The selected agreed price and PO line reconcile." },
        { name: "Decisive facts", result: isUnresolved ? "not_verified" as const : "passed" as const, explanation: isUnresolved ? "At least one decisive check remains unresolved." : "Dates, currency, SKU, quantity, and cited prices were available for deterministic comparison." }
      ],
      supportingEvidence: supported,
      contradictoryEvidence: contradictory,
      proposedDisposition: isUnresolved ? "needs_review" as const : finding.status === "potential_overcharge" ? "supported" as const : "rejected" as const,
      explanation: isUnresolved ? "The proposed discrepancy is not promoted: conflicting or incomplete agreement evidence requires human review." : finding.status === "potential_overcharge" ? "Deterministic price arithmetic supports this potential discrepancy; human review is still required before any claim." : "The checked evidence does not support an overcharge for this line."
    };
  }));
  const verified = await tracedVerification(async () => challenged.map(item => {
    const refs = [...item.supportingEvidence, ...item.contradictoryEvidence];
    const intact = refs.every(ref => docs.some(doc => doc.id === ref.sourceId && doc.pages.some(page => page.page === ref.page && page.text.includes(ref.excerpt))));
    return intact ? item : { ...item, checks: item.checks.map(check => check.name === "Citation integrity" ? { ...check, result: "failed" as const, explanation: "A supporting or contradictory evidence reference could not be reverified." } : check) };
  }));
  states.push("verify");
  const selfAudit = await tracedDecision(() => verified.map(({ proposedDisposition, ...item }) => ({
    ...item,
    disposition: item.checks.some(check => check.result === "failed" || check.result === "not_verified") ? "needs_review" as const : proposedDisposition
  })));
  states.push("decide");
  const warnings = audit.warnings;
  if (warnings.length || audit.status === "needs_review") return { state: "needs_review", case: audit, evidence, warnings, states: [...states, "needs_review"], selfAudit };
